  {kind==="bank"&&<><Field name="nickname" label="Account nickname" required/><Field name="bankName" label="Bank name" required/><Currency name="currency" label="Account currency"/><Field name="accountLast4" label="Account number (last 4)" required/><Field name="balance" label="Opening balance" type="number"/><label className="check wide"><input type="checkbox" name="isDefault"/> {t("Default receiving account")}</label></>}
  {(kind==="invoice"||kind==="invoice-edit")&&<>{editingInvoice&&<input type="hidden" name="invoiceId" value={editingInvoice.id}/>}<RowSelect name="templateId" label="Invoice template" rows={data.invoiceTemplates} value={String(editingInvoice?.template_id||"")} empty="Select template" required/><RowSelect name="orderId" label="Related order" rows={data.orders} keyName="order_no" value={String(editingInvoice?.order_id||"")} empty="Select order" required/><RowSelect name="bankAccountId" label="Receiving / paying account" rows={data.banks} keyName="nickname" value={String(editingInvoice?.bank_account_id||"")} required/><Field name="reference" label="Reference / purchase order" value={editingInvoice?.reference}/><Currency name="currency" label="Invoice currency" value={invoiceCurrency} onChange={setInvoiceCurrency}/><InvoiceLineGrid key={String(editingInvoice?.id??"new")} initialLines={buildInvoiceLines(editingInvoice?.id,data.invoiceItems,editingInvoice)} currency={invoiceCurrency}/><Field name="issueDate" label="Issue date" type="date" value={editingInvoice?.issue_date||today} required/><Field name="dueDate" label="Due date" type="date" value={editingInvoice?.due_date||today} required/><Field name="taxRate" label="Tax rate %" type="number" value={editingInvoice?.tax_rate}/><Field name="discountAmount" label="Discount amount" type="number" value={editingInvoice?.discount_amount}/><Field name="shippingAmount" label="Shipping amount" type="number" value={editingInvoice?.shipping_amount}/><TextArea name="notes" label="Notes" value={editingInvoice?.notes}/></>}
